use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let n = input["n"].as_u64().unwrap() as usize;
    let start = input["start"].as_u64().unwrap() as usize;
    let target = input["target"].as_u64().unwrap() as usize;
    let edges = input["edges"].as_array().unwrap();
    let mut graph = vec![vec![]; n];
    for edge in edges {
        let u = edge[0].as_u64().unwrap() as usize;
        let v = edge[1].as_u64().unwrap() as usize;
        graph[u].push(v);
        graph[v].push(u);
    }
    let mut distances = vec![i64::MAX; n];
    distances[start] = 0;
    let mut queue = vec![start];
    while !queue.is_empty() {
        let u = queue.pop().unwrap();
        for v in &graph[u] {
            if distances[v] < distances[u] + 1 {
                distances[v] = distances[u] + 1;
                queue.push(v);
            }
        }
    }
    if distances[target] == i64::MAX {
        Value::Null
    } else {
        Value::Number(serde_json::Number::from(distances[target]))
    }
}
